155	// =====================================================================
156	// fused_step — Stage 6 L3 persistent-megakernel dispatch (§1.12)
157	//
158	// PREFERS a fused TU when one is present for (model, optimizer, arch):
159	// the generated csrc/fused/<arch>/ megakernels register a host launcher per
160	// solver-chosen cell. fused_step detects the arch, looks up the cell, and —
161	// if a real fused TU is wired for it — dispatches there; otherwise it throws a
162	// descriptive NotImplemented so the caller falls through to the existing
163	// per-op path (which remains the default and is UNTOUCHED).
164	//
165	// HONESTY: only the cells whose megakernel was actually instantiated in
166	// csrc/fused/sm_90/megakernel_demo.cu are dispatched here. Every other cell
167	// throws "no fused TU; use per-op path". The set of wired cells is the
168	// SG_FUSED_CELLS table below — it is the C++ mirror of the cells the generator
169	// (grokking_optimizers/megakernel_codegen.py) emits to disk.
170	// =====================================================================
171	
172	#if defined(WITH_CUDA) && !defined(WITH_HIP)
173	namespace fused {
174	// The persistent-megakernel scratch the host zero-initializes (mirror of
175	// csrc/fused/megakernel_common.cuh::PersistentContext — kept layout-identical).
176	//
177	// This MUST live in sg::fused (NOT sg::fused::sm90): the real struct in
178	// megakernel_common.cuh is declared in sg::fused, so every generated cell .cu
179	// (which opens sg::fused::sm90 and names PersistentContext unqualified) binds
180	// sg::fused::PersistentContext via enclosing-namespace lookup. The dispatch
181	// table .inc below opens sg::fused::sm90 too, so it resolves this same shadow
182	// by the identical lookup — making the call-site mangling match the .cu
183	// definitions. A shadow in sg::fused::sm90 would mangle the cell parameter as
184	// sg::fused::sm90::PersistentContext and fail to link against the .cu symbols.
185	struct PersistentContext {
186	 int* g_next_task;
187	 unsigned* g_arrived;
188	 unsigned* g_generation;
189	 int n_tasks;
190	 unsigned n_ctas;
191	};
192	} // namespace fused
193	// Phase 3 Stage 5: all 33 sm_90 cells are real component compositions
194	// (csrc/fused/sm_90/mega_<model>_<opt>.cu → fused_megakernel.cuh →
195	// opt_components.cuh/model_stages.cuh). This generated table declares every
196	// cell launcher and routes (model, optimizer) → the real symbol. It replaces
197	// the 3 hard-coded demo routes (the toy megakernel_demo.cu was deleted).
198	#include "csrc/fused/sm_90/fused_dispatch_table.inc"
199	#endif
200	
201	// gfx942 twin (🟡 hipcc/MI300X only). Faithful mirror of the sm_90 block: the
202	// 33 gfx942 cells are real component compositions
203	// (csrc/fused/gfx942/mega_<m>_<o>.hip → fused_megakernel.hip.hpp →
204	// opt_components.hip.hpp/model_stages.hip.hpp), AMDGCN-gate-verified; their host
205	// hipLaunchKernelGGL launchers + this routing compile only under hipcc. The
206	// WITH_CUDA build #if-excludes this entire block.
207	#if defined(WITH_HIP)
208	#include <hip/hip_runtime.h>
209	namespace fused { namespace gfx942_mega {
210	struct PersistentContext {   // mirror of megakernel_common_hip.hip.hpp
211	 int* g_next_task;
212	 unsigned* g_arrived;
213	 unsigned* g_generation;
214	 int n_tasks;
215	 unsigned n_ctas;
216	};
217	}} // namespace fused::gfx942_mega
218	#include "csrc/fused/gfx942/fused_dispatch_table.inc"
219	#endif
220	
221	namespace {
222	
223	// Canonical name of the wired fused cell, or empty if none. This is the single
224	// source of truth in C++ for "which (model, optimizer, arch) has a real fused
225	// TU"; it is kept in sync with megakernel_codegen.py's wired-cell set.
226	// Phase 2: expanded to cover all 99 cells (3 models × 11 optimizers × 3 archs).
227	// Generated by: megakernel_codegen.py --dispatch-table
228	// wired_fused_cell — NOW generator-emitted (WS4): the C++ tier-tag map is
229	// derived from the same solver enumeration that emits the 99 cells, so it
230	// cannot hand-sync-drift. Regenerate via:
231	//   python -m grokking_optimizers.megakernel_codegen --dispatch-table > \
232	//     csrc/fused/fused_wired_cells.inc
233	#include "csrc/fused/fused_wired_cells.inc"
234	
235	#if defined(WITH_CUDA) || defined(WITH_HIP)
236	// Per-(device, n) reusable scratch for fused_step. The barrier counters and the
237	// `acts` proxy were previously reallocated (and `acts` memset over the full
238	// param size) on EVERY dispatch; sizes/offsets are constant for a given n.
239	// We persist them keyed by (device_index, n) and only reset the mutable parts
240	// (zero the 3 barrier counters + the acts buffer) per step. Behavior is
241	// identical — same zero-initialized scratch handed to the launcher — but the
242	// allocations/the full-size memset of sizes/offsets happen once per shape.
243	struct FusedScratch {
244	 torch::Tensor g_next;       // int32 [1]
245	 torch::Tensor g_arrived;    // int32 [1] (reinterpreted as unsigned)
246	 torch::Tensor g_generation; // int32 [1] (reinterpreted as unsigned)
247	 torch::Tensor sizes;        // int32 [1] = n  (constant per n)
248	 torch::Tensor offsets;      // int32 [1] = 0  (constant)
249	 torch::Tensor acts;         // float [numel(params)] proxy buffer
250	};
251	
252	// Keyed by (device_index, n). n disambiguates differing param shapes on the
253	// same device; acts is sized to params.numel() (== n here, single flat tensor).
254	inline FusedScratch& fused_scratch_for(const torch::Tensor& params, int64_t n) {
255	 static std::unordered_map<long long, FusedScratch> cache;
256	 const long long dev_idx =
257	 params.device().is_cuda() ? static_cast<long long>(params.device().index())
258	 : -1LL;
259	 const long long key = (dev_idx << 40) ^ static_cast<long long>(n);
260	 auto it = cache.find(key);
261	 if (it == cache.end()) {
262	 auto opts_i =
263	 torch::TensorOptions().device(params.device()).dtype(torch::kInt32);
264	 FusedScratch s;
265	 s.g_next = torch::zeros({1}, opts_i);
266	 s.g_arrived = torch::zeros({1}, opts_i);
267	 s.g_generation = torch::zeros({1}, opts_i);
268	 s.sizes = torch::full({1}, n, opts_i); // constant for this n
269	 s.offsets = torch::zeros({1}, opts_i); // constant
270	 s.acts = torch::zeros_like(params);
271	 it = cache.emplace(key, std::move(s)).first;
272	 } else {
273	 // Reset only the mutable scratch; sizes/offsets are invariant for this n.
274	 it->second.g_next.zero_();
275	 it->second.g_arrived.zero_();
276	 it->second.g_generation.zero_();
277	 it->second.acts.zero_();
278	 }
279	 return it->second;
280	}
281	#endif
282	
283	} // anonymous namespace
284	
285	void fused_step(const std::string& model, const std::string& optimizer,
286	 torch::Tensor params, torch::Tensor input,
287	 torch::Tensor grad, torch::Tensor state, float lr) {
288	 int arch = detect_arch();
289	 std::string arch_str = (arch == 90) ? "sm_90"
290	 : (arch == 942) ? "gfx942" : "tpu_v6e";
291	
292	 const std::string cell = wired_fused_cell(model, optimizer, arch);
293	 if (cell.empty()) {
294	 // §1.12 fall-through: no fused TU for this cell. The caller uses the
295	 // existing per-op dispatch (the per-optimizer *_fused_step bindings),
296	 // which is untouched. We surface a clear, non-silent signal.
297	 throw std::runtime_error(
298	 "no fused TU for (" + model + ", " + optimizer + ", " + arch_str +
299	 "); use the per-op path. Wired L3 cells: (mamba3,adamw), "
300	 "(transformer_decoder,lion), (vit,supergrok15).");
301	 }
302	
303	#if defined(WITH_CUDA) && !defined(WITH_HIP)
304	 if (arch == 90) {
305	 // Prepare the megakernel inputs from the tensors. The persistent scratch
306	 // (task counter + barrier state) is device-allocated and zero-initialized
307	 // here; the host launcher pins one CTA per SM. `state` carries the
308	 // optimizer state slices (m, v) concatenated; sizes/offsets describe the
309	 // per-parameter-tensor layout (here the single flattened tensor).
310	 //
311	 // Keep the element count in int64 at this boundary: a large flat param
312	 // ( > 2^31-1 elements ) truncated to `int` would wrap negative, making
313	 // the `3*n` state-size check pass spuriously and the `m + n` / `m + 2*n`
314	 // pointer offsets index out of bounds (silent OOB corruption). The
315	 // numel-derived state check and pointer math below all use this int64 n.
316	 const int64_t n = params.numel();
317	
318	 // Reusable per-(device,n) scratch: counters/acts reset, sizes/offsets fixed.
319	 FusedScratch& sc = fused_scratch_for(params, n);
320	
321	 // acts proxy + the m/v halves of state.
322	 auto p = params.data_ptr<float>();
323	 auto in = input.numel() ? input.data_ptr<float>() : p;
324	 auto gr = grad.numel() ? grad.data_ptr<float>() : sc.acts.data_ptr<float>();
325	 // state holds [m | v | extra]; split it. `extra` is the per-optimizer third
326	 // per-element buffer (ema/sam_dir/s_track/mu/orth/smart_grad); each cell binds
327	 // it to its FusedOptState field (adamw/lion/neuralgrok ignore it). Sized 3n.
328	 // An undersized state tensor was previously silently replaced by a fresh
329	 // zero buffer that was DISCARDED after the call (the optimizer state never
330	 // persisted) and reallocated every step — a latent correctness bug plus a
331	 // hot-path realloc. Surface it instead of silently corrupting state.
332	 if (state.numel() < 3 * n) {
333	 throw std::runtime_error(
334	 "fused_step: state tensor for (" + model + ", " + optimizer +
335	 ") has " + std::to_string(state.numel()) + " elements but needs at "
336	 "least 3*n = " + std::to_string(3 * n) +
337	 " (m|v|extra). Pass a persistent, correctly-sized state tensor.");
338	 }
339	 float* m = state.data_ptr<float>();
340	 float* v = m + n;
341	 float* extra = m + 2 * n;
342	
343	 // The megakernel ABI (PersistentContext.n_tasks, the int32 sizes/offsets
344	 // tensors) is 32-bit per the layout-identical mirror struct and the
345	 // generated launchers. The fused indices are being widened by the fused
346	 // agent; until the device-side N is int64, fail loudly rather than feed a
347	 // truncated count into the kernel (which would silently process the wrong
348	 // task range). This gate fires only for params with > 2^31-1 elements.
349	 TORCH_CHECK(n <= static_cast<int64_t>(std::numeric_limits<int>::max()),
350	 "fused_step: param has ", n, " elements, exceeding the int32 "
351	 "megakernel ABI (PersistentContext.n_tasks / sizes / offsets). "
352	 "Use the per-op path for params with > 2^31-1 elements.");
353	
354	 fused::PersistentContext ctx{
355	 sc.g_next.data_ptr<int>(),
356	 reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
357	 reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
358	 // n_tasks = number of work tasks = #entries in sizes/offsets (one slab per
359	 // parameter tensor; a single flat tensor here → 1). It is NOT the element
360	 // count: the megakernel loops `t < n_tasks` reading sizes[t]/offsets[t], so
361	 // n_tasks=n would index both 1-element arrays ~n entries out of bounds and
362	 // feed garbage offsets into params[] (a multi-GB OOB read). n_ctas (0 here)
363	 // is overwritten by the launcher with one persistent CTA per SM.
364	 static_cast<int>(sc.sizes.numel()), 0u};
365	
366	 // Use the current CUDA stream so the megakernel orders against the rest of
367	 // the model's work and is capturable in a CUDA graph (the legacy default
368	 // stream 0 serialized against all work and blocked graph capture).
369	 cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
370	
371	 // Route to the real composed cell launcher (all 33 sm_90 cells). `found`
372	 // is set false only if no cell matches (then we fall through to the honest
373	 // not-compiled signal below).
374	 bool found = false;
375	 cudaError_t err = fused::sm90::dispatch_sm90_cell(
376	 model, optimizer, ctx, p, in, sc.acts.data_ptr<float>(), gr, m, v, extra,
377	 sc.sizes.data_ptr<int>(), sc.offsets.data_ptr<int>(), lr, /*step=*/1,
378	 stream, &found);
379	
380	 if (found) {
381	 if (err != cudaSuccess)
382	 throw std::runtime_error(
383	 std::string("fused megakernel launch failed for ") + cell + ": " +
384	 cudaGetErrorString(err));
385	 return;
386	 }
387	 }
388	#endif
389	
390	#if defined(WITH_HIP)
391	 if (arch == 942) {
392	 // gfx942 real composition route (hipcc/MI300X). Mirror of the sm_90 path.
393	 // int64 element count at the boundary (see the sm_90 path for rationale):
394	 // a truncated `int` numel would wrap negative and make the 3*n check and
395	 // m+n/m+2*n pointer math index out of bounds.
396	 const int64_t n = params.numel();
397	 FusedScratch& sc = fused_scratch_for(params, n);
398	 auto p = params.data_ptr<float>();
399	 auto in = input.numel() ? input.data_ptr<float>() : p;
400	 auto gr = grad.numel() ? grad.data_ptr<float>() : sc.acts.data_ptr<float>();
401	 if (state.numel() < 3 * n) {
402	 throw std::runtime_error(
403	 "fused_step: state tensor for (" + model + ", " + optimizer +
404	 ") has " + std::to_string(state.numel()) + " elements but needs at "
405	 "least 3*n = " + std::to_string(3 * n) +
406	 " (m|v|extra). Pass a persistent, correctly-sized state tensor.");
407	 }
408	 float* m = state.data_ptr<float>();
409	 float* v = m + n; float* extra = m + 2 * n;
410	 // int32 megakernel ABI gate (mirror of the sm_90 path).
411	 TORCH_CHECK(n <= static_cast<int64_t>(std::numeric_limits<int>::max()),
412	 "fused_step: param has ", n, " elements, exceeding the int32 "
413	 "megakernel ABI. Use the per-op path for > 2^31-1 elements.");
414	 fused::gfx942_mega::PersistentContext ctx{
415	 sc.g_next.data_ptr<int>(),
416	 reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
417	 reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
418	 // n_tasks = TASK count (sizes/offsets entries), NOT the element count n —
419	 // the megakernel loops t < n_tasks reading sizes[t]/offsets[t]; passing n
420	 // here was the same multi-GB OOB the sm_90 path fixed (47d8007), left
421	 // unfixed on this HIP twin until now.
422	 static_cast<int>(sc.sizes.numel()), 0u};
423	 // Current HIP stream for graph capture / proper ordering (was default 0).
424	 hipStream_t stream = c10::hip::getCurrentHIPStream().stream();
425	 bool found = false;
426	 hipError_t herr = fused::gfx942_mega::dispatch_gfx942_cell(
427	 model, optimizer, ctx, p, in, sc.acts.data_ptr<float>(), gr, m, v, extra,
428	 sc.sizes.data_ptr<int>(), sc.offsets.data_ptr<int>(), lr, 1, stream, &found);
429	 if (found) {
430	 if (herr != hipSuccess)
431	 throw std::runtime_error(
432	 std::string("gfx942 fused megakernel launch failed for ") + cell +
433	 ": " + hipGetErrorString(herr));
434	 return;
435	 }
436	 }
437	#endif
438	
439	 // The cell is "wired" in the manifest but its TU is not compiled into THIS
440	 // build (CPU/host build has no fused TU). Surface it honestly.
441	 throw std::runtime_error(
442	 "fused TU for " + cell + " is manifest-registered but not compiled into "
443	 "this build (CPU build has no fused TU). Use the per-op path.");
444	}
445	
446	} // namespace sg
