54	// =========================================================================
55	//  Optimizer stage — the fused tail. Pulls tensors from the queue and applies
56	//  the REAL apply_optimizer<Opt> elementwise over this SM's resident state
57	//  slice (kept L2-warm via the %smid pin, §1.3).
58	// =========================================================================
59	// #6 — per-Opt pointer rebase via `if constexpr`. Rather than unconditionally
60	// bumping all 8 optimizer-state pointers per task (8 predicated adds + the
61	// chance the allocator keeps every field live), only the pointers the CHOSEN
62	// optimizer actually dereferences are rebased to the tensor slice; the rest are
63	// compiled out. `ts` starts as a copy of the const& `st` (the scalar
64	// hyperparams must be present), but the dead-pointer rebases vanish, lowering
65	// the local/register footprint of the tail.
66	template <OptId Opt>
67	__device__ __forceinline__ FusedOptState rebase_state(const FusedOptState& st,
68	                                                       int64_t off) {
69	    FusedOptState ts = st;
70	    if constexpr (Opt == OptId::AdamW || Opt == OptId::Lion ||
71	                  Opt == OptId::Grokfast || Opt == OptId::GrokAdamW ||
72	                  Opt == OptId::LookSAM || Opt == OptId::Prodigy ||
73	                  Opt == OptId::NeuralGrok || Opt == OptId::SuperGrok11 ||
74	                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2) {
75	        if (ts.exp_avg)    ts.exp_avg    += off;   // m (all Adam-family tails)
76	    }
77	    if constexpr (Opt != OptId::Lion && Opt != OptId::Muon) {
78	        if (ts.exp_avg_sq) ts.exp_avg_sq += off;   // v (everyone but Lion/Muon)
79	    }
80	    if constexpr (Opt == OptId::Grokfast || Opt == OptId::GrokAdamW) {
81	        if (ts.ema)        ts.ema        += off;
82	    }
83	    if constexpr (Opt == OptId::Prodigy) {
84	        if (ts.s_track)    ts.s_track    += off;
85	    }
86	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
87	        if (ts.mu)         ts.mu         += off;
88	    }
89	    if constexpr (Opt == OptId::LookSAM) {
90	        if (ts.sam_dir)    ts.sam_dir    += off;
91	    }
92	    if constexpr (Opt == OptId::Muon) {
93	        if (ts.orth)       ts.orth       += off;
94	    }
95	    if constexpr (Opt == OptId::SuperGrok2) {
96	        if (ts.smart_grad) ts.smart_grad += off;
97	    }
98	    return ts;
99	}
