101	template <OptId Opt>
102	__device__ void fused_optimizer_stage(const PersistentContext& ctx,
103	                                       float* __restrict__ params,
104	                                       const float* __restrict__ grad,
105	                                       const int* sizes, const int* offsets,
106	                                       int step, const FusedOptState& st) {
107	    __shared__ int task_slot;
108	    TaskQueue q = ctx.queue();
109	    for (int t = q.next_block(&task_slot); t < ctx.n_tasks;
110	         t = q.next_block(&task_slot)) {
111	        const int n = sizes[t];
112	        // #2 int64: off is the tensor's element offset into the global param
113	        // blob and can exceed 2^31; rebase the slice pointers in 64-bit so the
114	        // base address is correct past 2 Gi elements. The within-tensor index
115	        // (base/i below) is bounded by n (an int) but apply_optimizer takes an
116	        // int64_t idx so the addition never truncates. Behavior-preserving.
117	        const int64_t off = (int64_t)offsets[t];
118	        // #6: rebase only the pointers Opt uses to this tensor's slice.
119	        const FusedOptState ts = rebase_state<Opt>(st, off);
120	        float* __restrict__ p = params + off;
121	        const float* __restrict__ g = grad + off;
122	        // #1 — float4 vectorization of the per-element tail. Each thread strides
123	        // over groups of 4 CONSECUTIVE indices and calls the canonical per-
124	        // element optimizer fn 4× on [4j .. 4j+3]; because the four indices are
125	        // contiguous and the buffers are __restrict__, the loads/stores of
126	        // params/grad/m/v coalesce into 128-bit float4 transactions. The
127	        // canonical algorithm math (csrc/algorithms/<opt>.h via apply_optimizer)
128	        // is CALLED, never re-inlined — only the loop's access pattern changes.
129	        const int n4 = n >> 2;                  // # of full float4 groups
130	        for (int j = threadIdx.x; j < n4; j += blockDim.x) {
131	            const int64_t base = (int64_t)j << 2;   // #2 int64 within-tensor idx
132	            apply_optimizer<Opt>(p, g, base + 0, step, ts);
133	            apply_optimizer<Opt>(p, g, base + 1, step, ts);
134	            apply_optimizer<Opt>(p, g, base + 2, step, ts);
135	            apply_optimizer<Opt>(p, g, base + 3, step, ts);
136	        }
137	        // Scalar tail for the remainder (n not a multiple of 4).
138	        for (int i = (n4 << 2) + (int)threadIdx.x; i < n; i += blockDim.x) {
139	            apply_optimizer<Opt>(p, g, (int64_t)i, step, ts);
140	        }
141	    }
142	}
