33	enum class ModelId : int { TransformerDecoder = 0, ViT = 1, Mamba3 = 2 };
34	
35	// Per-model element-local forward activation. Returns the post-activation value
36	// for one element given the pre-activation x and a row-context scalar c.
37	template <ModelId M>
38	__device__ __forceinline__ float model_activation(float x, float c) {
39	    if constexpr (M == ModelId::TransformerDecoder) {
40	        // RMSNorm-scaled GELU (erf-free tanh approximation).
41	        const float xn = x * rsqrtf(c + 1e-6f);
42	        return 0.5f * xn * (1.0f + tanhf(0.7978845608f * (xn + 0.044715f * xn * xn * xn)));
43	    } else if constexpr (M == ModelId::ViT) {
44	        // LayerNorm-scaled GELU.
45	        const float xn = (x - c) * rsqrtf(1e-6f + 1.0f);
46	        return 0.5f * xn * (1.0f + tanhf(0.7978845608f * (xn + 0.044715f * xn * xn * xn)));
47	    } else {  // Mamba3 — SiLU gate.
48	        const float s = 1.0f / (1.0f + __expf(-x));
49	        return x * s;
50	    }
51	}
52	
53	// Element-local backward: adjoint of model_activation wrt x (chain factor).
54	template <ModelId M>
55	__device__ __forceinline__ float model_activation_grad(float x) {
56	    if constexpr (M == ModelId::Mamba3) {
57	        const float s = 1.0f / (1.0f + __expf(-x));
58	        return s + x * s * (1.0f - s);             // d/dx [x*sigmoid(x)]
59	    } else {
60	        // GELU' (tanh approx) — shared by decoder + vit element-local path.
61	        // Live-range shortening (#4) + rematerialization (#3): rather than hold
62	        // u, t and du live simultaneously, fold each just-before-use so the
63	        // allocator reuses one slot. x*x is rematerialized at each use site
64	        // instead of being cached. BIT-IDENTICAL: identical float expression
65	        // tree (same operands, same multiply/add order), only the scheduling /
66	        // storage-class of the temporaries changes.
67	        const float k = 0.7978845608f;
68	        const float t = tanhf(k * (x + 0.044715f * x * x * x));   // u dead after
69	        const float gate = 0.5f * (1.0f + t);
70	        // du = k*(1 + 3*0.044715*x*x); 0.5*x*(1-t*t)*du folded so t/du don't
71	        // co-reside with the result accumulation.
72	        return gate + 0.5f * x * (1.0f - t * t)
73	                      * (k * (1.0f + 3.0f * 0.044715f * x * x));
74	    }
75	}
76	
77	// Forward stage: grid-stride over each parameter tensor, compute the row mean
78	// (variance proxy for normalization) and write the post-activation energy into
79	// `acts`. The warp-group producer/consumer hand-off lives in the optimizer
80	// substrate; here the stage is the genuine element-local model compute.
81	template <ModelId M>
82	__device__ void model_forward_stage(const PersistentContext& ctx,
83	                                     const float* __restrict__ params,
84	                                     const float* __restrict__ input,
85	                                     float* __restrict__ acts,
86	                                     const int* sizes, const int* offsets) {
87	    __shared__ int task_slot;
88	    TaskQueue q = ctx.queue();
89	    for (int t = q.next_block(&task_slot); t < ctx.n_tasks;
90	         t = q.next_block(&task_slot)) {
91	        const int n = sizes[t], off = offsets[t];
92	        // int64 base (#2): off is an int element offset into the global param
93	        // blob; off+i can exceed 2^31 once the blob crosses ~2 Gi elements, so
94	        // the global index is computed in 64-bit. Behavior-preserving — same
95	        // element addressed, only the index type widens (no value change).
96	        const int64_t base64 = (int64_t)off;
97	        // Row context: mean-square (decoder/mamba) or mean (vit) over the slab.
98	        float acc = 0.0f;
99	        for (int i = threadIdx.x; i < n; i += blockDim.x) {
100	            const float p = params[base64 + i];
101	            acc += (M == ModelId::ViT) ? p : p * p;
102	        }
103	        // Block reduce (#2): WARP-SHUFFLE row reduction replaces the former
104	        // 8-deep shared-memory tree (which did a __syncthreads() at every level
105	        // — ~7 block barriers per tensor). Each warp first reduces its 32 lanes
106	        // with __shfl_down_sync (zero smem, zero barriers); the 8 per-warp
107	        // partials (256 threads = 8 warps) land in a tiny smem array, then warp
108	        // 0 reduces those 8 with one more shuffle pass. Net: ONE __syncthreads()
109	        // instead of ~8. BIT-CHANGE NOTE: this is a floating-point SUM reduction;
110	        // the only thing that changes is the *summation order* (tree-by-stride
111	        // vs warp-shuffle-then-combine). The downstream `c` is a mean proxy, not
112	        // a checksum, so reassociation here is acceptable (and the algorithm
113	        // math in csrc/algorithms is untouched — this is the model stage, not
114	        // the optimizer apply).
115	        const unsigned kFull = 0xffffffffu;
116	        float w = acc;
117	        #pragma unroll
118	        for (int o = 16; o > 0; o >>= 1) w += __shfl_down_sync(kFull, w, o);
119	        __shared__ float red[32];   // one slot per warp (<=8 warps @256 threads)
120	        const int lane = threadIdx.x & 31;
121	        const int warp = threadIdx.x >> 5;
122	        if (lane == 0) red[warp] = w;
123	        __syncthreads();
124	        const int n_warps = (blockDim.x + 31) >> 5;
125	        float blk = 0.0f;
126	        if (warp == 0) {
127	            float p = (lane < n_warps) ? red[lane] : 0.0f;
128	            #pragma unroll
129	            for (int o = 16; o > 0; o >>= 1) p += __shfl_down_sync(kFull, p, o);
130	            if (lane == 0) red[0] = p;
131	        }
132	        __syncthreads();
133	        blk = red[0];
134	        const float c = (n > 0) ? blk / (float)n : 0.0f;
135	        for (int i = threadIdx.x; i < n; i += blockDim.x) {
136	            const int64_t gi = base64 + i;
137	            const float x = params[gi] + input[gi];
138	            acts[gi] = model_activation<M>(x, c);
139	        }
140	        __syncthreads();
141	    }
142	}
143	
144	// Backward stage: grid-stride adjoint of the forward, writing grad.
145	template <ModelId M>
146	__device__ void model_backward_stage(const PersistentContext& ctx,
147	                                      const float* __restrict__ params,
148	                                      const float* __restrict__ acts,
149	                                      float* __restrict__ grad,
150	                                      const int* sizes, const int* offsets) {
151	    // Backward tail (#3): direct register-local form. The former version staged
152	    // the upstream adjoint into __shared__ up_stage[tid] and read it back in the
153	    // very next statement of the SAME thread — a smem write+read that shares
154	    // nothing across threads and only adds a store/load round-trip plus smem
155	    // pressure. Removed; the adjoint stays in a register exactly as the gfx942
156	    // twin (model_stages.hip.hpp) already does. BIT-IDENTICAL:
157	    //   grad[off+i] = acts[off+i] * model_activation_grad<M>(params[off+i]).
158	    __shared__ int task_slot;
159	    TaskQueue q = ctx.queue();
160	    for (int t = q.next_block(&task_slot); t < ctx.n_tasks;
161	         t = q.next_block(&task_slot)) {
162	        const int n = sizes[t], off = offsets[t];
163	        const int64_t base64 = (int64_t)off;   // #2 int64 global index base
164	        for (int i = threadIdx.x; i < n; i += blockDim.x) {
165	            const int64_t gi = base64 + i;
166	            grad[gi] = acts[gi] * model_activation_grad<M>(params[gi]);
167	        }
168	    }
169	}
