29	template <typename ParamT, typename GradT>
30	__device__ __forceinline__ void adamw_step(
31	    ParamT* __restrict__ param,
32	    float* __restrict__ exp_avg,
33	    float* __restrict__ exp_avg_sq,
34	    const GradT* __restrict__ grad,
35	    const float lr,
36	    const float beta1,
37	    const float beta2,
38	    const float eps,
39	    const float wd,
40	    const float bc1,   // 1 - beta1^t (un-inverted; header divides by it)
41	    const float bc2,   // 1 - beta2^t (un-inverted; header divides by it)
42	    const int64_t idx
43	) {
44	    const float g  = static_cast<float>(grad[idx]);
45	    const float p  = static_cast<float>(param[idx]);
46	    const float m0 = exp_avg[idx];
47	    const float v0 = exp_avg_sq[idx];
48	
49	    const float m = beta1 * m0 + (1.0f - beta1) * g;
50	    const float v = beta2 * v0 + (1.0f - beta2) * g * g;
51	
52	    // Bias correction: m_hat = m / (1 - beta1^t), v_hat = v / (1 - beta2^t).
53	    const float m_hat = m / sg_safe_bc(bc1);
54	    const float v_hat = v / sg_safe_bc(bc2);
55	
56	    const float denom = sqrtf(v_hat) + eps;
57	    const float update = m_hat / denom;
58	
59	    exp_avg[idx]    = m;
60	    exp_avg_sq[idx] = v;
61	    param[idx]      = static_cast<ParamT>(p - lr * (update + wd * p));
62	}
