39	// A CUDA build links ONLY sg::sm90 symbols; a HIP build ONLY sg::gfx942. A
40	// `case` that calls the other arch's namespace is an undefined symbol that
41	// makes the .so fail to load (e.g. sg::gfx942::moe_filter_active_params in a
42	// CUDA-only build — the gfx942 .hip TUs are never compiled by nvcc). Gate each
43	// case by its backend macro, mirroring dispatch.cpp's WITH_CUDA/WITH_HIP split,
44	// so the Python front-end binds exactly the backend that was compiled in.
45	// (WITH_HIP wins if both are somehow defined, matching dispatch.cpp.)
46	#if defined(WITH_CUDA) && !defined(WITH_HIP)
47	#  define SG_CASE_SM90_RET(METHOD, ...)  case 90:  return ::sg::sm90::METHOD(__VA_ARGS__);
48	#  define SG_CASE_SM90_CALL(METHOD, ...) case 90:  ::sg::sm90::METHOD(__VA_ARGS__); break;
49	#else
50	#  define SG_CASE_SM90_RET(METHOD, ...)
51	#  define SG_CASE_SM90_CALL(METHOD, ...)
52	#endif
